func EscalatedNEQ(v bool) predicate.SuspensionCase {
	return predicate.SuspensionCase(sql.FieldNEQ(FieldEscalated, v))
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.SuspensionCase) predicate.SuspensionCase {
	return predicate.SuspensionCase(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.SuspensionCase) predicate.SuspensionCase {
	return predicate.SuspensionCase(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.SuspensionCase) predicate.SuspensionCase {
	return predicate.SuspensionCase(sql.NotPredicates(p))
}
